contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry used by the checker
    function run(address asset, uint256 depositAmount) public payable {
        // no preconditions on params
        // read-before state
        uint256 beforeTotal = c.getTotalAssetDeposits(asset);
        uint256 beforePoolBalance = IERC20(asset).balanceOf(address(c));

        // attempt deposit. We must be caller that the contract thinks is msg.sender — this contract
        bool reverted;
        try c.depositAsset(asset, depositAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read-after state
        uint256 afterTotal = c.getTotalAssetDeposits(asset);
        uint256 afterPoolBalance = IERC20(asset).balanceOf(address(c));

        // general rule: if depositAsset succeeded (did not revert) then the total deposits
        // increased by exactly depositAmount and the pool's balance increased by depositAmount;
        // if it reverted then neither total nor pool balance increased.
        assert(
            (!reverted && afterTotal == beforeTotal + depositAmount && afterPoolBalance == beforePoolBalance + depositAmount)
            || (reverted && afterTotal == beforeTotal && afterPoolBalance == beforePoolBalance)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry used by the checker
    function run(address asset, uint256 depositAmount) public payable {
        // No preconditions on params

        // Read-before values (views only)
        uint256 beforePoolBalance = IERC20(asset).balanceOf(address(c));

        // Read oracle-derived expected minted amount before calling (uses only public calls)
        address oracleAddr = c.lrtConfig().getContract(LRTConstants.LRT_ORACLE);
        ILRTOracle oracle = ILRTOracle(oracleAddr);
        uint256 assetPrice = oracle.getAssetPrice(asset);
        uint256 rsethPrice = oracle.getRSETHPrice();
        uint256 expectedMint = 0;
        if (rsethPrice != 0) {
            expectedMint = (depositAmount * assetPrice) / rsethPrice;
        }

        // Perform depositAsset and catch revert flag. This is a top-level state-changing call on c.
        bool reverted;
        try c.depositAsset(asset, depositAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read-after values
        uint256 afterPoolBalance = IERC20(asset).balanceOf(address(c));

        // General rule asserted:
        // - If depositAsset succeeded (did not revert): the pool's asset balance increased by depositAmount,
        //   and the expectedMint computed from the oracle equals the rseth amount that would be minted.
        //   We cannot directly observe rseth mint, but lrtConfig.rsETH() and its token balance change for msg.sender
        //   are not observable here (mint goes to msg.sender). Instead we assert the oracle-derived formula is well-formed
        //   (rsethPrice != 0 implies expectedMint matches the contract's getRsETHAmountToMint view) and the pool balance increased.
        // - If it reverted: the pool's asset balance did not increase.

        // obtain what contract computes for rseth via public view
        uint256 contractComputedMint = c.getRsETHAmountToMint(asset, depositAmount);

        assert(
            (!reverted && afterPoolBalance == beforePoolBalance + depositAmount && (rsethPrice == 0 ? contractComputedMint == 0 : contractComputedMint == expectedMint))
            || (reverted && afterPoolBalance == beforePoolBalance)
        );
    }

    receive() external payable {}
}

