contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry used by the checker
    function run(address[] calldata nodeDelegators) public payable {
        // observe length before
        uint256 beforeLen = c.getNodeDelegatorQueue().length;

        // perform the state-changing call as a top-level statement and record whether it reverted
        bool reverted;
        try c.addNodeDelegatorContractToQueue(nodeDelegators) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe length after
        uint256 afterLen = c.getNodeDelegatorQueue().length;

        // If the call reverted, length must be unchanged.
        // If it succeeded, length must increase by exactly nodeDelegators.length and the appended entries must match inputs.
        if (reverted) {
            assert(afterLen == beforeLen);
        } else {
            uint256 N = nodeDelegators.length;
            assert(afterLen == beforeLen + N);
            // check that each appended element equals the corresponding input
            for (uint256 i = 0; i < N; ) {
                address queued = c.getNodeDelegatorQueue()[beforeLen + i];
                assert(queued == nodeDelegators[i]);
                unchecked { ++i; }
            }
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address[] calldata nodeDelegators) public payable {
        uint256 beforeLen = c.getNodeDelegatorQueue().length;

        bool reverted;
        try c.addNodeDelegatorContractToQueue(nodeDelegators) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterLen = c.getNodeDelegatorQueue().length;

        // Build a single general assertion covering both cases:
        // If reverted => afterLen == beforeLen.
        // If not reverted => afterLen == beforeLen + nodeDelegators.length AND every appended entry equals the input in order.
        // Expressed as one assert boolean.
        uint256 N = nodeDelegators.length;
        bool appendedMatches = true;
        if (!reverted) {
            // check appended entries match inputs
            for (uint256 i = 0; i < N; ) {
                address queued = c.getNodeDelegatorQueue()[beforeLen + i];
                if (queued != nodeDelegators[i]) {
                    appendedMatches = false;
                    break;
                }
                unchecked { ++i; }
            }
        }

        assert(
            (reverted && afterLen == beforeLen) ||
            (!reverted && afterLen == beforeLen + N && appendedMatches)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that will be fuzzed with arbitrary params
    function run(address asset, uint256 depositAmount) public payable {
        require(address(this).balance >= 0);
        // Preconditions: ensure asset is marked supported by lrtConfig would normally be required,
        // but we can't call internal config. So we observe behavior: call getTotalAssetDeposits before,
        // then try depositAsset and catch revert. The invariant we assert relates pre/post totals and revert flag.

        // read-before value
        uint256 beforeTotal = c.getTotalAssetDeposits(asset);

        bool reverted;
        try c.depositAsset(asset, depositAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotal = c.getTotalAssetDeposits(asset);

        // General rule:
        // If the call succeeded (not reverted) then afterTotal >= beforeTotal and the increase is at most depositAmount + some allowance
        // (we assert increase is >= depositAmount when token transfer succeeded). However we cannot detect token transfer success separately.
        // We assert: if not reverted then afterTotal >= beforeTotal + 0 (no loss) AND afterTotal >= beforeTotal (monotonic non-decrease).
        // Additionally, if depositAmount > 0 and the call did not revert then afterTotal - beforeTotal >= 1 when depositAmount>=1 (i.e., some increase proportional to positive deposit).

        // Compose a general property combining monotonicity and that successful deposit cannot reduce total deposits.
        assert((reverted) || (afterTotal >= beforeTotal));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public fuzz entry: provide an array of addresses and an admin caller must be msg.sender of this contract
    function run(address[] calldata nodeDelegators) public payable {
        // limit input size to avoid very large loops in the verifier
        require(nodeDelegators.length <= 10);

        // read before-length
        uint256 beforeLen = c.getNodeDelegatorQueue().length;

        bool reverted;
        try c.addNodeDelegatorContractToQueue(nodeDelegators) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterLen = c.getNodeDelegatorQueue().length;

        // Count how many of the provided addresses are non-zero (since UtilLib.checkNonZeroAddress rejects zero)
        uint256 nonZeroCount = 0;
        for (uint256 i = 0; i < nodeDelegators.length; ) {
            if (nodeDelegators[i] != address(0)) {
                nonZeroCount++;
            }
            unchecked { ++i; }
        }

        // General rule:
        // If the call did not revert, then afterLen == beforeLen + nonZeroCount.
        // If the call reverted, then afterLen == beforeLen (no partial push on revert).
        assert((!reverted && afterLen == beforeLen + nonZeroCount) || (reverted && afterLen == beforeLen));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params: index into queue, token asset address, transfer amount
    function run(uint256 ndcIndex, address asset, uint256 amount) public payable {
        // keep inputs bounded to help verifier
        require(ndcIndex < 5);
        require(amount <= type(uint128).max);

        // Observe before balances via public surface
        uint256 poolBefore = IERC20(asset).balanceOf(address(c));
        address[] memory queue = c.getNodeDelegatorQueue();
        // If index out of current queue range, calling will revert; allow that case
        uint256 ndcBalanceBefore = 0;
        if (ndcIndex < queue.length) {
            ndcBalanceBefore = IERC20(asset).balanceOf(queue[ndcIndex]);
        }

        bool reverted;
        try c.transferAssetToNodeDelegator(ndcIndex, asset, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 poolAfter = IERC20(asset).balanceOf(address(c));
        uint256 ndcBalanceAfter = 0;
        if (ndcIndex < queue.length) {
            ndcBalanceAfter = IERC20(asset).balanceOf(queue[ndcIndex]);
        }

        // General conservation rule: if the call succeeded then (poolAfter + ndcAfter) == (poolBefore + ndcBefore)
        // If the call reverted then balances must be unchanged (no partial effects)
        assert((!reverted && poolAfter + ndcBalanceAfter == poolBefore + ndcBalanceBefore) || (reverted && poolAfter == poolBefore && ndcBalanceAfter == ndcBalanceBefore));
    }

    receive() external payable {}
}

