contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Single public entry that exercises depositAsset and asserts a general invariant.
    // Params:
    // - asset: token address to deposit (must be supported by lrtConfig; otherwise depositAsset should revert with AssetNotSupported)
    // - depositAmount: amount attempted to deposit
    function run(address asset, uint256 depositAmount) public payable {
        require(true);

        // Read observable state before the action
        uint256 beforeTotal = c.getTotalAssetDeposits(asset);

        // Attempt depositAsset and observe whether it reverted
        bool reverted;
        try c.depositAsset(asset, depositAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable state after the action
        uint256 afterTotal = c.getTotalAssetDeposits(asset);

        // General rule (single assert):
        // If the call did not revert then depositAmount must be > 0 and <= getAssetCurrentLimit(asset) and afterTotal >= beforeTotal.
        // If the call reverted then either depositAmount == 0 or depositAmount > getAssetCurrentLimit(asset) or asset not supported or token transfer failed.
        // We express a forward implication that when not reverted the obvious safety properties hold and total deposits did not decrease.
        assert(
            reverted
            || (
                // non-reverted path
                depositAmount != 0
                && depositAmount <= c.getAssetCurrentLimit(asset)
                && afterTotal >= beforeTotal
            )
        );
    }

    receive() external payable {}
}
